// Runs EXPLAIN (ANALYZE, BUFFERS) against the exact SQL generated by hot page APIs.
process.env.NEST_COMPAT_MODE = 'true';
if (process.env.DIAGNOSE_SCHEMA_SETUP !== 'true') process.env.SKIP_SCHEMA_SETUP = 'true';
process.env.ZOHO_SYNC_WORKER = 'false';
process.env.ZOHO_AUTO_SYNC = 'false';
process.env.GMAIL_AUTO_SYNC = 'false';
process.env.EVENT_AUTO_SYNC = 'false';
process.env.ZOOM_AUTO_SYNC = 'false';

const { __leadsTest, server } = require('../server.js');

(async () => {
  const baseline = await __leadsTest.explainBootstrapAndLeads({
    limit: process.env.EXPLAIN_LEADS_LIMIT || 100,
    include_total: process.env.EXPLAIN_LEADS_INCLUDE_TOTAL || 'false'
  });
  const remaining_pages = await __leadsTest.explainRemainingPageQueries({
    leads_limit: process.env.EXPLAIN_LEADS_LIMIT || 100
  });
  const result = { baseline, remaining_pages };
  console.log(JSON.stringify(result, null, 2));
})().then(() => {
  try { server.close(); } catch {}
  process.exit(0);
}).catch(error => {
  console.error(error.stack || error.message);
  try { server.close(); } catch {}
  process.exit(1);
});
